#include <cstdio>
#include <cstdlib>
#include <cmath>
#include <cuda_runtime.h>

#define CHECK_CUDA(call)                                                      \
    do {                                                                      \
        cudaError_t err__ = (call);                                           \
        if (err__ != cudaSuccess) {                                           \
            printf("CUDA error at %s:%d -> %s\n", __FILE__, __LINE__,         \
                   cudaGetErrorString(err__));                                \
            exit(EXIT_FAILURE);                                               \
        }                                                                     \
    } while (0)

__global__ void vectorAdd(const float* __restrict__ a,
                          const float* __restrict__ b,
                          float* __restrict__ c,
                          int n) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < n) {
        c[idx] = a[idx] + b[idx];
    }
}

int main() {
    const int N = 1 << 20;              // 1,048,576 elements
    const size_t bytes = N * sizeof(float);
    const int blockSize = 256;
    const int gridSize = (N + blockSize - 1) / blockSize;

    printf("=== CUDA Vector Addition ===\n");
    printf("N            : %d\n", N);
    printf("Data size    : %.2f MiB per buffer\n", bytes / (1024.0 * 1024.0));
    printf("Block size   : %d\n", blockSize);
    printf("Grid size    : %d\n", gridSize);
    printf("Total threads: %d\n\n", (long long)gridSize * blockSize);

    // ---- Device properties ----
    int dev = 0;
    CHECK_CUDA(cudaGetDevice(&dev));
    cudaDeviceProp prop;
    CHECK_CUDA(cudaGetDeviceProperties(&prop, dev));
    printf("Device       : %s\n", prop.name);
    printf("Compute Cap. : %d.%d\n", prop.major, prop.minor);
    printf("SMs          : %d\n", prop.multiProcessorCount);
    printf("Max threads/block: %d\n", prop.maxThreadsPerBlock);
    printf("Global mem   : %.2f MiB\n\n", prop.totalGlobalMem / (1024.0 * 1024.0));

    // ---- Host allocation (pinned) ----
    float *h_a, *h_b, *h_c, *h_ref;
    CHECK_CUDA(cudaMallocHost((void**)&h_a, bytes));
    CHECK_CUDA(cudaMallocHost((void**)&h_b, bytes));
    CHECK_CUDA(cudaMallocHost((void**)&h_c, bytes));
    h_ref = (float*)malloc(bytes);

    for (int i = 0; i < N; ++i) {
        h_a[i] = (float)(i % 1000) * 0.5f;
        h_b[i] = (float)((i * 7) % 1000) * 0.25f;
        h_c[i] = -1.0f;
        h_ref[i] = h_a[i] + h_b[i];   // CPU reference
    }

    // ---- Device allocation + transfer ----
    float *d_a, *d_b, *d_c;
    CHECK_CUDA(cudaMalloc((void**)&d_a, bytes));
    CHECK_CUDA(cudaMalloc((void**)&d_b, bytes));
    CHECK_CUDA(cudaMalloc((void**)&d_c, bytes));

    cudaEvent_t start, stop;
    CHECK_CUDA(cudaEventCreate(&start));
    CHECK_CUDA(cudaEventCreate(&stop));

    CHECK_CUDA(cudaMemcpy(d_a, h_a, bytes, cudaMemcpyHostToDevice));
    CHECK_CUDA(cudaMemcpy(d_b, h_b, bytes, cudaMemcpyHostToDevice));

    // ---- Kernel launch (timed) ----
    CHECK_CUDA(cudaEventRecord(start));
    vectorAdd<<<gridSize, blockSize>>>(d_a, d_b, d_c, N);
    CHECK_CUDA(cudaGetLastError());     // launch config errors
    CHECK_CUDA(cudaEventRecord(stop));
    CHECK_CUDA(cudaEventSynchronize(stop));   // catches async execution errors
    CHECK_CUDA(cudaDeviceSynchronize());

    float ms = 0.0f;
    CHECK_CUDA(cudaEventElapsedTime(&ms, start, stop));

    CHECK_CUDA(cudaMemcpy(h_c, d_c, bytes, cudaMemcpyDeviceToHost));

    // ---- Verification ----
    int mismatches = 0;
    for (int i = 0; i < N; ++i) {
        if (fabsf(h_c[i] - h_ref[i]) > 1e-2f) {
            if (mismatches < 5) {
                printf("MISMATCH at index %d: gpu=%f cpu=%f\n",
                       i, h_c[i], h_ref[i]);
            }
            ++mismatches;
        }
    }

    printf("Kernel time  : %.4f ms\n", ms);
    printf("Throughput   : %.2f GB/s (read+write)\n",
           (3.0 * bytes) / (ms * 1e-3) / 1e9);
    printf("Mismatches   : %d / %d\n", mismatches, N);
    printf("Spot check   : c[0]=%f  c[%d]=%f\n", h_c[0], N - 1, h_c[N - 1]);

    int rc = 0;
    if (mismatches == 0) {
        printf("\nRESULT: PASS - all %d elements correct.\n", N);
    } else {
        printf("\nRESULT: FAIL - %d incorrect elements.\n", mismatches);
        rc = 1;
    }

    CHECK_CUDA(cudaEventDestroy(start));
    CHECK_CUDA(cudaEventDestroy(stop));
    CHECK_CUDA(cudaFree(d_a));
    CHECK_CUDA(cudaFree(d_b));
    CHECK_CUDA(cudaFree(d_c));
    CHECK_CUDA(cudaFreeHost(h_a));
    CHECK_CUDA(cudaFreeHost(h_b));
    CHECK_CUDA(cudaFreeHost(h_c));
    free(h_ref);

    return rc;
}
